{
  "schemaVersion": 1,
  "weenieClassId": 42047186,
  "mutators": ["shaman", "enchanter", "warder"],
  "rules": [
    {
      "id": "phase_01_release_inhibitions", "trigger": "combat_start", "chancePercent": 100, "minPlayers": 1, "once": true,
      "actions": [
        {"type": "set_phase", "phase": "phase_01_release"},
        {"type": "say", "text": "I WILL CAST RELEASE YOUR INHIBITIONS!"},
        {"type": "effect", "effect": "PortalStorm"},
        {"type": "frost_rain", "target": "all", "count": 2, "damageScale": 0.15},
        {"type": "taunt", "channel": "fellowship", "text": "[%b] Leave certainty at the door. Tonight, even the sky comes loose."}
      ]
    },
    {
      "id": "phase_02_open_window", "trigger": "health_below", "thresholdPercent": 85, "chancePercent": 100, "minPlayers": 1, "once": true,
      "actions": [
        {"type": "set_phase", "phase": "phase_02_open_window"},
        {"type": "say", "text": "Open every shutter. Let the weather find you."},
        {"type": "scatter", "target": "all", "distance": 18},
        {"type": "frost_rain", "target": "all", "count": 3, "damageScale": 0.18}
      ]
    },
    {
      "id": "phase_03_feel_the_rain", "trigger": "health_below", "thresholdPercent": 70, "chancePercent": 100, "minPlayers": 1, "once": true,
      "actions": [
        {"type": "set_phase", "phase": "phase_03_feel_the_rain"},
        {"type": "taunt", "channel": "local", "text": "The storm has learned your name, %t. Let it write in frost."},
        {"type": "frost_rain", "target": "all", "count": 5, "damageScale": 0.24},
        {"type": "effect", "effect": "EnchantUpBlue"}
      ]
    },
    {
      "id": "phase_04_unwritten_path", "trigger": "health_below", "thresholdPercent": 55, "chancePercent": 100, "minPlayers": 1, "once": true,
      "actions": [
        {"type": "set_phase", "phase": "phase_04_unwritten_path"},
        {"type": "say", "text": "No map can save you. Choose the next step while the ground refuses to wait."},
        {"type": "pull", "target": "farthest", "distance": 24},
        {"type": "push", "target": "nearest", "distance": 16},
        {"type": "maintain_minions", "weenieClassId": 7, "count": 3, "health": 100},
        {"type": "frost_rain", "target": "random", "count": 3, "damageScale": 0.22}
      ]
    },
    {
      "id": "phase_05_unspoken_chorus", "trigger": "health_below", "thresholdPercent": 40, "chancePercent": 100, "minPlayers": 1, "once": true,
      "actions": [
        {"type": "set_phase", "phase": "phase_05_unspoken_chorus"},
        {"type": "taunt", "channel": "fellowship", "text": "[%b] Every word you swallowed has joined the thunder."},
        {"type": "scatter", "target": "all", "distance": 24},
        {"type": "frost_rain", "target": "all", "count": 5, "damageScale": 0.28},
        {"type": "effect", "effect": "BreatheLightning"}
      ]
    },
    {
      "id": "phase_06_arms_open", "trigger": "health_below", "thresholdPercent": 20, "chancePercent": 100, "minPlayers": 1, "once": true,
      "actions": [
        {"type": "set_phase", "phase": "phase_06_arms_open"},
        {"type": "say", "text": "Come with empty hands and open arms. The last page belongs to the storm."},
        {"type": "pull", "target": "all", "distance": 18},
        {"type": "knock_up", "target": "all", "distance": 26},
        {"type": "frost_rain", "target": "all", "count": 7, "damageScale": 0.32},
        {"type": "effect", "effect": "TransUpWhite"}
      ]
    },
    {
      "id": "window_drizzle", "trigger": "timer", "intervalSeconds": 16, "chancePercent": 60, "minPlayers": 1, "once": false, "phase": "phase_02_open_window",
      "actions": [
        {"type": "taunt", "channel": "local", "text": "A little weather through the window..."},
        {"type": "frost_rain", "target": "random", "count": 2, "damageScale": 0.16}
      ]
    },
    {
      "id": "rainfall_rhythm", "trigger": "timer", "intervalSeconds": 12, "chancePercent": 72, "minPlayers": 1, "once": false, "phase": "phase_03_feel_the_rain",
      "actions": [
        {"type": "taunt", "channel": "local", "text": "Drop by drop, the storm finishes its sentence."},
        {"type": "frost_rain", "target": "all", "count": 3, "damageScale": 0.20}
      ]
    },
    {
      "id": "thunder_rhythm", "trigger": "timer", "intervalSeconds": 14, "chancePercent": 75, "minPlayers": 1, "once": false, "phase": "phase_05_unspoken_chorus",
      "actions": [
        {"type": "taunt", "channel": "fellowship", "text": "[%b] The chorus chooses %t for the high note."},
        {"type": "push", "target": "trigger", "distance": 20},
        {"type": "frost_rain", "target": "all", "count": 3, "damageScale": 0.24},
        {"type": "effect", "effect": "BreatheLightning"}
      ]
    },
    {
      "id": "resist_stomp", "trigger": "spell_resisted", "chancePercent": 45, "minPlayers": 1, "once": true,
      "actions": [
        {"type": "taunt", "channel": "local", "text": "Your spell bounced. You may follow it."},
        {"type": "knock_up", "target": "trigger", "distance": 32},
        {"type": "frost_rain", "target": "trigger", "count": 2, "damageScale": 0.20}
      ]
    },
    {
      "id": "death_last_note", "trigger": "death", "chancePercent": 100, "minPlayers": 1, "once": true,
      "actions": [
        {"type": "say", "text": "Fine. Keep the sky. I was finished with it."},
        {"type": "effect", "effect": "TransDownBlack"}
      ]
    }
  ]
}

